COPY={}
def page(n,en,es,se,ss,ce,cs,fe,fs):
 COPY[f'DD-{n:03d}']={'en':dict(title=en[0],intro=en[1],sections=se,checklist=ce,faq=fe),'es':dict(title=es[0],intro=es[1],sections=ss,checklist=cs,faq=fs)}
page(78,('Doberman ear care: observe first, clean only with a suitable plan','Comfortable external observation is different from treating an ear problem. New odor, discharge, redness or pain needs veterinary advice rather than a stronger cleaner or an improvised home remedy.'),('Oídos: observa primero y sigue un plan adecuado','Observar el exterior con comodidad es distinto de tratar un problema. Olor, secreción, enrojecimiento o dolor nuevos necesitan consulta, no un limpiador más fuerte ni remedios improvisados.'),[
('Look at the outside without forcing access','Choose a calm setting and allow your dog to move away. Observe the visible ear flap and changes you can describe without inserting anything into the canal. Note head shaking, scratching or sensitivity that is new for your dog. Appearance alone cannot tell you which condition is present.'),('Ask whether cleaning is needed','Ask your veterinarian which product and technique, if any, suit your dog’s ears and current needs. Over-cleaning can irritate tissue. A general routine should not turn odor or discomfort into a reason to repeatedly flush an unassessed ear. Follow individual instructions for any prescribed care.'),('Keep tools and products appropriate','Do not insert cotton swabs into the ear canal or use hydrogen peroxide or homemade mixtures. Read the selected product label and keep it in its original container. Request a professional demonstration before attempting unfamiliar care, particularly if your dog is uncomfortable or has a history of ear problems.'),('A worked observation note','Example: yesterday the dog accepted gentle ear-flap contact; today there is a new smell and the dog pulls away. Stop handling and contact the veterinary team, describing the onset and response. This note helps explain a concern; it does not diagnose infection or authorize a cleaning treatment.'),('Pause when comfort changes','Stop for pain, panic or struggling and seek veterinary advice. Keep any prescribed instructions and product details available to caregivers so tasks are not duplicated. Do not assume cropped or natural ears remove the need for individual assessment, and do not impose a fixed cleaning interval on every Doberman.')],[
('Observa sin forzar','Elige tranquilidad y permite alejarse. Observa pabellón visible sin introducir nada en el conducto. Anota sacudidas, rascado o sensibilidad nuevos. El aspecto no identifica por sí solo una enfermedad.'),('Pregunta si hace falta limpiar','Consulta producto y técnica adecuados. Limpiar demasiado puede irritar. Olor o molestias no justifican lavados repetidos sin valoración. Sigue instrucciones individuales de cuidados prescritos.'),('Utiliza material adecuado','No introduzcas bastoncillos ni uses agua oxigenada o mezclas caseras. Lee etiqueta y conserva envase. Solicita demostración antes de cuidados desconocidos, especialmente con molestias o historial de problemas.'),('Ejemplo de observación','Ayer aceptaba contacto suave; hoy hay olor nuevo y se aparta. Para y consulta describiendo inicio y respuesta. Ayuda a explicar, sin diagnosticar infección ni autorizar tratamiento.'),('Para cuando cambie comodidad','Dolor, pánico o forcejeo requieren parar y consultar. Comparte instrucciones y productos con cuidadores. Orejas naturales o modificadas no eliminan valoración individual; no impongas intervalo universal.')],['Observe the visible ear and handling comfort.','Record new odor, discharge or sensitivity.','Ask about an appropriate product and demonstration.','Stop for pain; follow individual veterinary instructions.'],['Observa exterior y comodidad.','Anota olor, secreción o sensibilidad nuevos.','Consulta producto y demostración.','Para ante dolor y sigue instrucciones.'],[('Should I clean every Doberman’s ears weekly?','No. Discuss actual need and individual instructions; excessive cleaning can cause irritation.'),('Can I diagnose an ear infection from a photo?','No. Ask a veterinarian about new pain, odor, discharge or other changes.')],[('¿Limpio cada semana a todos?','No. Consulta necesidad e instrucciones; exceso puede irritar.'),('¿Diagnostico por foto?','No. Consulta dolor, olor, secreción u otros cambios.')])
page(79,('Doberman dental care: build comfortable brushing and arrange assessment','Gradual home brushing supports care between veterinary assessments. Choose suitable dog products and comfortable handling; toys or chews do not establish that a mouth is healthy or replace professional evaluation.'),('Cuidado dental: cepillado cómodo y valoración','El cepillado gradual apoya cuidados entre revisiones. Elige productos caninos y manejo cómodo; juguetes o mordedores no demuestran salud ni sustituyen evaluación profesional.'),[
('Ask about the mouth before starting','Discuss dental care with your veterinary team, especially for pain, bleeding, persistent bad breath or difficulty eating. An awake look at the mouth cannot evaluate every tooth or the structures below the gumline. Do not force brushing over a painful area or scrape deposits off at home.'),('Choose a dog brush and toothpaste','Ask about a suitable soft brush and toothpaste intended for dogs. Human toothpaste and improvised products are not substitutes. Read the label and keep products away from unsupervised chewing. A professional demonstration can help with handling and product selection.'),('Introduce contact in small comfortable steps','Begin with the dog choosing to remain near you and accepting an easy brief touch around the mouth. Introduce the brush gradually, allowing breaks and withdrawal. When your dog is comfortable and you have appropriate guidance, gently brush accessible outer tooth surfaces. Build the routine without restraining through fear or pain.'),('A worked practice record','Example: today the dog calmly investigates the brush and accepts a brief lip touch; next step—repeat that easy contact before adding brushing. Record the tolerated step and any discomfort. Completing an introduction is not the same as cleaning the whole mouth or proving that dental disease is absent.'),('Keep home care within its limits','Ask your veterinarian how to plan ongoing brushing, examinations and any necessary professional procedures for this dog. Check evidence for dental products rather than assuming a chew replaces brushing. Pause and seek advice for discomfort or new changes, even if a checklist says a session is due.')],[
('Consulta antes de empezar','Habla de dolor, sangrado, mal olor persistente o dificultad para comer. Mirar la boca despierto no valora todos los dientes ni estructuras bajo encía. No cepilles a la fuerza una zona dolorosa ni raspes depósitos en casa.'),('Elige cepillo y pasta caninos','Consulta cepillo suave y pasta para perros. Pasta humana y productos improvisados no sustituyen. Lee etiqueta y guarda lejos de masticación. Pide demostración para manejo y selección.'),('Introduce contacto por pasos','Empieza por permanecer voluntariamente cerca y aceptar contacto breve fácil. Presenta cepillo gradualmente con pausas y retirada. Con comodidad y orientación, cepilla suavemente caras exteriores accesibles. No sujetes para soportar miedo o dolor.'),('Ejemplo de práctica','Hoy explora cepillo y acepta contacto breve del labio; siguiente paso: repetir antes de añadir cepillado. Anota tolerancia y molestias. Introducir herramienta no equivale a limpiar todo ni descartar enfermedad.'),('Respeta límites domésticos','Consulta plan de cepillado, revisiones y procedimientos necesarios. Busca evidencia de productos sin asumir que mordedor sustituye cepillado. Para y consulta ante cambios, aunque toque una sesión.')],['Discuss mouth discomfort and an individual care plan.','Use suitable dog brush and toothpaste.','Introduce handling gradually with breaks.','Record comfort and keep veterinary assessments in the plan.'],['Consulta molestias y plan individual.','Utiliza cepillo y pasta adecuados.','Introduce manejo con pausas.','Anota comodidad y mantén revisiones.'],[('Do dental chews replace all dental care?','No. Assess specific product evidence with your veterinarian and maintain an individual brushing and assessment plan.'),('Should I brush if my dog shows pain?','Stop and contact your veterinary team instead of forcing the task.')],[('¿Mordedores sustituyen todos los cuidados?','No. Consulta evidencia y mantén plan individual de cepillado y revisión.'),('¿Cepillo si duele?','Para y contacta con el veterinario sin forzar.')])
page(80,('Doberman paw care: comfortable checks after everyday activity','Notice changes in pads, nails and movement without forcing handling. Surface conditions and your dog’s response matter more than a universal temperature rule or a product’s protective promise.'),('Patas: revisión cómoda después de actividad','Observa almohadillas, uñas y movimiento sin forzar. Importan superficie y respuesta individual, no una regla universal de temperatura ni promesas de protección.'),[
('Start with movement and willingness','Watch for limping, persistent licking or reluctance to place weight before handling a paw. Use a stable nonslip position and introduce touch gently. Stop if the dog withdraws, becomes tense or appears painful; gripping harder is not a useful inspection method.'),('Observe visible changes safely','Look for visible damage, redness, swelling or material around the paw without probing or cutting tissue. Ask your veterinarian about embedded objects or suspected injury rather than attempting invasive removal. Record which paw and when the change was first noticed.'),('Plan for the surface and conditions','Consider hot pavement, ice, grit and other irritating or hazardous surfaces. Choose safer routes and respond to the dog’s comfort rather than relying on a single air-temperature cutoff. After ordinary dirty outings, use a suitable gentle cleaning method and dry comfortably; suspected chemical exposure needs professional advice.'),('A worked post-walk record','Example: your dog normally walks comfortably but begins licking one paw after a gravel route. Note the location, onset and visible findings, stop further irritating activity and contact the veterinary team if concern persists or injury is suspected. Do not repeat the route to test a reaction or diagnose from a photograph.'),('Evaluate products without guarantees','Check intended use, fit, ingredients or materials and manufacturer instructions for any paw-care product. Boots need gradual introduction and movement checks; a balm does not guarantee protection from heat or eliminate the need for assessment. Keep nail trimming as a separate skill with professional demonstration when needed.')],[
('Empieza por movimiento','Observa cojera, lamido persistente o evitar apoyo antes de tocar. Usa postura estable antideslizante y contacto gradual. Para ante retirada, tensión o dolor; sujetar más no mejora revisión.'),('Observa cambios visibles','Revisa daño, enrojecimiento, hinchazón o material sin pinchar ni cortar. Consulta objetos incrustados o lesión en vez de retirar de forma invasiva. Anota pata e inicio.'),('Planifica superficies','Valora pavimento caliente, hielo, gravilla y sustancias irritantes. Elige rutas seguras y respuesta individual sin confiar en un corte de temperatura. Tras suciedad habitual, limpia suavemente y seca; exposición química sospechada necesita orientación.'),('Ejemplo después de paseo','Camina normalmente pero lame una pata tras gravilla. Anota lugar, inicio y hallazgos; evita más irritación y consulta si persiste o sospechas lesión. No repitas ruta para probar ni diagnostiques por foto.'),('Evalúa productos sin garantías','Revisa uso, ajuste, ingredientes o materiales e instrucciones. Botas requieren presentación y comprobar movimiento; un bálsamo no garantiza protección térmica ni sustituye valoración. Cortaúñas es otra habilidad con demostración si hace falta.')],['Observe gait before touching paws.','Check visible changes without probing.','Record the paw, surface and onset.','Seek advice for injury, discomfort or chemical exposure.'],['Observa marcha antes de tocar.','Revisa cambios visibles sin pinchar.','Anota pata, superficie e inicio.','Consulta lesión, molestias o químicos.'],[('Can paw balm make hot pavement safe?','Do not assume that. Choose safer conditions and routes and follow individual care advice.'),('Should I pull out an embedded object?','Ask your veterinarian about suspected embedded material or injury rather than attempting invasive removal.')],[('¿Bálsamo hace seguro pavimento caliente?','No lo supongas. Elige condiciones y rutas seguras.'),('¿Retiro un objeto incrustado?','Consulta en vez de intentar retirada invasiva.')])
